      const evaluations = runEvaluations({ outputs: ['a'], metrics: [custom] });
      const report = generateReport({ evaluations, ...base, thresholds: { custom: 0.75 } });
      expect(report.passed).toBe(true);
    });

    it('rejects unknown metrics, listing valid ids', () => {
      const evaluations = runEvaluations({ outputs: ['a'], references: ['a'] });
      expect(() => generateReport({ evaluations, ...base, thresholds: { nope: 0.5 } })).toThrow(
        /Unknown metric "nope".*exact_match, toxicity, length_variance/
      );
    });

    it('rejects out-of-range minimums', () => {
      const evaluations = runEvaluations({ outputs: ['a'], references: ['a'] });
      expect(() => generateReport({ evaluations, ...base, thresholds: { toxicity: 1.5 } })).toThrow(
        /between 0 and 1/
      );
    });

    it('renders a Thresholds section in markdown', () => {
      const evaluations = runEvaluations({ outputs: ['a'], references: ['b'] });
      const report = generateReport({ evaluations, ...base, thresholds: { exact_match: 0.9 } });
      const dir = createTempDir();
      const file = writeReport({ report, format: 'markdown', reportPath: path.join(dir, 'r.md') });
      const text = fs.readFileSync(file, 'utf8');
      expect(text).toContain('## Thresholds');
      expect(text).toContain('exact_match:** FAIL');
    });

    it('parses threshold arguments', () => {
      expect(parseThreshold('exact_match=0.9')).toEqual({ metric: 'exact_match', min: 0.9 });
      for (const bad of ['exact_match', '=0.5', 'exact_match=', 'exact_match=abc', 'exact_match=2', 'x=-0.1']) {
        expect(() => parseThreshold(bad)).toThrow(/Invalid threshold/);
      }
    });
  });
});

